var n=`0085-papanasi`;var a=`world-0085`;var r=`RO`;var s=`eastern-europe`;var t=6;var o=35;var g={en:`Papanași`,ua:`Папанаші`};var l={en:`A classic dish from Romania, featuring farmer cheese, chicken egg, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: домашній кисломолочний сир, куряче яйце, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`farmer-cheese`,500,`g`],[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,160,`g`],[`white-granulated-sugar`,85,`g`],[`baking-powder`,7,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 11 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 11 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:11,i:[[`sunflower-oil`,700,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`sour-cream`,180,`g`],[`strawberry-jam`,160,`g`]]}];var u={slug:n,id:a,country:`RO`,region:s,servings:6,minutes:35,title:g,text:l,steps:d};export{r as country,u as default,a as id,o as minutes,s as region,t as servings,n as slug,d as steps,l as text,g as title};